package com.example.lovenotes;
import android.app.*;import android.appwidget.AppWidgetManager;import android.os.Bundle;import android.content.*;import android.net.Uri;import android.graphics.Color;import android.widget.*;
public class MainActivity extends Activity {
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);layout.setPadding(40,90,40,40);layout.setBackgroundColor(Color.rgb(255,224,189));TextView title=new TextView(this);title.setText("A little love on your home screen.");title.setTextSize(28);title.setTextColor(Color.rgb(96,66,45));layout.addView(title);TextView help=new TextView(this);help.setText("Sign in at notes.example.com, open the home-screen section, and create a widget code. Paste it here, then add the Love Notes widget from your home screen.");help.setTextSize(16);help.setPadding(0,25,0,25);layout.addView(help);EditText code=new EditText(this);code.setHint("12-character pairing code");code.setSingleLine(true);code.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS);layout.addView(code);TextView status=new TextView(this);Button pair=new Button(this);pair.setText("Connect my widget ♡");layout.addView(pair);layout.addView(status);Button open=new Button(this);open.setText("Open Love Notes");layout.addView(open);open.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(Connection.ORIGIN))));Button pin=new Button(this);pin.setText("Add widget to home screen");layout.addView(pin);pin.setOnClickListener(v->{AppWidgetManager manager=AppWidgetManager.getInstance(this);if(manager.isRequestPinAppWidgetSupported())manager.requestPinAppWidget(new ComponentName(this,LoveWidget.class),null,null);else status.setText("Long-press your home screen, choose Widgets, then Love Notes.");});pair.setOnClickListener(v->{String value=code.getText().toString().trim();if(value.length()!=12){status.setText("Enter the 12-character code from the website.");return;}pair.setEnabled(false);status.setText("Connecting…");new Thread(()->{try{org.json.JSONObject result=Connection.request("/api/widget-connect",null,new org.json.JSONObject().put("code",value));Connection.save(this,result.getString("token"));runOnUiThread(()->{status.setText("Connected! Add the widget to your home screen.");code.setText("");pair.setEnabled(true);LoveWidget.refreshAll(this);});}catch(Exception e){runOnUiThread(()->{status.setText(e.getMessage());pair.setEnabled(true);});}}).start();});setContentView(layout);}
}
